\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% Venue Color Theme
\definecolor{primary}{HTML}{4A3525}     % deep aged-ink brown
\definecolor{secondary}{HTML}{8B4513} % saddle brown
\definecolor{accent}{HTML}{C83200}       % burnt orange / deep red
\definecolor{bgposter}{HTML}{FDFBF7}    % parchment tint
\definecolor{redbg}{HTML}{FFF8F6}
\definecolor{bluebg}{HTML}{F6F8F3}
\definecolor{darkbg}{HTML}{F8F6F4}
\definecolor{redtitlebg}{HTML}{FDEAE8}
\definecolor{bluetitlebg}{HTML}{E8F0E4}
\definecolor{darktitlebg}{HTML}{F0EAE5}
\definecolor{textdark}{HTML}{2B1D14}
\definecolor{textgray}{HTML}{5C4A3D}
\definecolor{stathighlight}{HTML}{FDEEE6}

\pagecolor{bgposter}
\color{textdark}

% List styling
\setlist[itemize]{leftmargin=24pt, itemsep=12pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=12pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% Figure macro
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[6mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{4mm}%
}

% Card styles
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% == TITLE BAR ==
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{76}\selectfont\bfseries THE HISTORY OF BOOKS}\\[12pt]
  {\fontsize{42}{50}\selectfont From Manuscripts to Mass Production}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{white!80} A Data-Driven Cultural Retrospective | The Arc of Knowledge over 1,500 Years}
}

% == STATS BANNER ==
\posterbox[
  enhanced, colback=primary!15!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!35},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} \textasciitilde1440}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Gutenberg's Press Invented}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 10 Cent.}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Manuscript Era Duration}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} >49}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Pages per UNESCO Book Definition}\vspace{8pt}%
    }}
  \end{minipage}
}

% == COL 1 ==
\posterbox[redcard, title={The Manuscript Era (6th-15th C.)}
]{name=manuscripts, column=1, between=row5 and row10}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item \textbf{Slow, scarce growth} across ten centuries
    \item Texts manually produced on parchment and papyrus
    \item \textbf{High-cost luxury} restricted to elites and clergy
    \item Notable growth milestones:
    \begin{itemize}
        \item \textit{9th Cent.}: Carolingian Renaissance
        \item \textit{12th Cent.}: Rise of universities
    \end{itemize}
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \centering\textbf{Scarcity:} Peak manuscript output in 15th century remained miniscule vs print.
  }}
}

\posterbox[bluecard, title={Modern Publishing \& Consumption}
]{name=modern, column=1, between=row10 and row16}{
  \fontsize{30}{40}\selectfont
  \posterfig{0.96}{figures/per_capita.pdf}{New book titles published per million people (Annual)}
  \begin{itemize}
    \item \textbf{Global publishing matures} globally by 1950s
    \item \textbf{Massive country variation} in per capita titles
    \item Output reflects education system investment
  \end{itemize}
}

\posterbox[highlightcard, title={Books as a Mirror of Society}
]{name=mirror, column=1, between=row16 and bottom}{
  \fontsize{30}{40}\selectfont
  Book production serves as a powerful proxy for several dimensions of human development:
  \begin{itemize}
    \item \textbf{Literacy Rates}: Tracks population reading skill
    \item \textbf{Income \& Wealth}: Affordable print signals prosperity
    \item \textbf{Education}: Driven by expanding school systems
    \item \textbf{Cultural Shift}: From religious to secular works
  \end{itemize}
}

% == COL 2 ==
\posterbox[darkcard, title={The Gutenberg Revolution (\textasciitilde1440)}
]{name=gutenberg, column=2, between=row5 and row16}{
  \fontsize{30}{40}\selectfont
  \posterfig{0.96}{figures/timeline.pdf}{Volume comparison: Written manuscripts vs. Printed books}
  \begin{itemize}
    \item Single most \textbf{transformative event} in publishing history
    \item Printed books rapidly replaced handwritten copies
    \item \textbf{Explosive growth}: Output multiplied across Western Europe by 1500-1550
    \item \textbf{Mass commodity}: Price collapsed, democratizing access
  \end{itemize}
  \vspace{12pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\textbf{Impact}: Industrial printing enabled global mass production by the 1800s.
  }}
}

\posterbox[redcard, title={Sources \& Data Context}
]{name=sources, column=2, between=row16 and bottom}{
  \fontsize{26}{36}\selectfont
  \textbf{Key Datasets:}
  \begin{itemize}[itemsep=8pt]
    \item Buringh, E. \& Van Zanden, J.L. (2009). \textit{Charting the Rise of the West: Manuscripts and Printed Books}. Journal of Economic History.
    \item Fink-Jensen, J. (2015). \textit{IISH Data Collection}.
    \item Roser, M. \& Ritchie, H. (2023). \textit{Books}. Our World in Data.
  \end{itemize}
  \vspace{16pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \centering Data spans 6th-15th century (manuscripts) and 1500-2009 (print per half-century \& per year).
  }}
}

\end{tcbposter}
\end{document}
EOF

